namespace Touchfish {
// Explicit public whitelist. Private fields added to MatchPlayer never enter a snapshot automatically.
public sealed class PublicPlayerState {
 public string HeroFormId,HeroAbilityId;public int HeroMaxHealth;public bool HeroDestroyed;public string ClassId,WeaponId,EmoteText;
 public bool FreeSecretThisTurn,Frozen,PowerUsed,WeaponWindfury,MulliganDone;
 public int Shadowform,Health,Armor,MaxMana,Mana,Overload,LockedMana,Fatigue,SecretCount,MinionsPlayedThisTurn,HeroAttacks,TempAttack,FrozenTurn,WeaponInstanceId,WeaponAttack,WeaponDurability,SecretImmuneTurn,CommandingShoutTurn,PreparationDiscount,FreeSpellsUntilTurn,ReportedHandCount;
 public static PublicPlayerState From(MatchPlayer p){return new PublicPlayerState{HeroFormId=p.HeroFormId,HeroAbilityId=p.HeroAbilityId,HeroMaxHealth=p.HeroMaxHealth,HeroDestroyed=p.HeroDestroyed,FreeSecretThisTurn=p.FreeSecretThisTurn,ClassId=p.ClassId,WeaponId=p.WeaponId,EmoteText=p.EmoteText,Frozen=p.Frozen,PowerUsed=p.PowerUsed,WeaponWindfury=p.WeaponWindfury,MulliganDone=p.MulliganDone,Shadowform=p.Shadowform,Health=p.Health,Armor=p.Armor,MaxMana=p.MaxMana,Mana=p.Mana,Overload=p.Overload,LockedMana=p.LockedMana,Fatigue=p.Fatigue,SecretCount=p.SecretCount,MinionsPlayedThisTurn=p.MinionsPlayedThisTurn,HeroAttacks=p.HeroAttacks,TempAttack=p.TempAttack,FrozenTurn=p.FrozenTurn,WeaponInstanceId=p.WeaponInstanceId,WeaponAttack=p.WeaponAttack,WeaponDurability=p.WeaponDurability,SecretImmuneTurn=p.SecretImmuneTurn,CommandingShoutTurn=p.CommandingShoutTurn,PreparationDiscount=p.PreparationDiscount,FreeSpellsUntilTurn=p.FreeSpellsUntilTurn,ReportedHandCount=p.ReportedHandCount};}
 public void Apply(MatchPlayer p){p.HeroFormId=HeroFormId;p.HeroAbilityId=HeroAbilityId;p.HeroMaxHealth=HeroMaxHealth;p.HeroDestroyed=HeroDestroyed;p.FreeSecretThisTurn=FreeSecretThisTurn;p.ClassId=ClassId;p.WeaponId=WeaponId;p.EmoteText=EmoteText;p.Frozen=Frozen;p.PowerUsed=PowerUsed;p.WeaponWindfury=WeaponWindfury;p.MulliganDone=MulliganDone;p.Shadowform=Shadowform;p.Health=Health;p.Armor=Armor;p.MaxMana=MaxMana;p.Mana=Mana;p.Overload=Overload;p.LockedMana=LockedMana;p.Fatigue=Fatigue;p.SecretCount=SecretCount;p.MinionsPlayedThisTurn=MinionsPlayedThisTurn;p.HeroAttacks=HeroAttacks;p.TempAttack=TempAttack;p.FrozenTurn=FrozenTurn;p.WeaponInstanceId=WeaponInstanceId;p.WeaponAttack=WeaponAttack;p.WeaponDurability=WeaponDurability;p.SecretImmuneTurn=SecretImmuneTurn;p.CommandingShoutTurn=CommandingShoutTurn;p.PreparationDiscount=PreparationDiscount;p.FreeSpellsUntilTurn=FreeSpellsUntilTurn;p.ReportedHandCount=ReportedHandCount;}
}
public static class BattleUnitCopies {
 public static void Copy(BattleUnit source,BattleUnit target){
target.Id=source.Id;target.Owner=source.Owner;target.BaseAttack=source.BaseAttack;target.BaseHealth=source.BaseHealth;target.DamageTaken=source.DamageTaken;target.AuraHealth=source.AuraHealth;target.TempAttack=source.TempAttack;target.AttacksUsed=source.AttacksUsed;target.SummonTurn=source.SummonTurn;target.FrozenTurn=source.FrozenTurn;target.DeathAnchor=source.DeathAnchor;target.ForestDeathrattles=source.ForestDeathrattles;target.WisdomBlessings0=source.WisdomBlessings0;target.WisdomBlessings1=source.WisdomBlessings1;target.StealthExpirySeat=source.StealthExpirySeat;target.StealthUntilTurn=source.StealthUntilTurn;target.OriginalOwner=source.OriginalOwner;target.DestroyAtEnd=source.DestroyAtEnd;target.DestroyAtStart0=source.DestroyAtStart0;target.DestroyAtStart1=source.DestroyAtStart1;target.ReturnSeat=source.ReturnSeat;target.ReturnTurn=source.ReturnTurn;target.CardId=source.CardId;target.Race=source.Race;target.Taunt=source.Taunt;target.Shield=source.Shield;target.Windfury=source.Windfury;target.Charge=source.Charge;target.Poison=source.Poison;target.Stealth=source.Stealth;target.Frozen=source.Frozen;target.Silenced=source.Silenced;target.SpellDamage=source.SpellDamage;target.Enchantments=new EnchantmentCollection();foreach(var e in source.Enchantments.Items)target.Enchantments.Items.Add(new Enchantment{Kind=e.Kind,Attack=e.Attack,Health=e.Health,Amount=e.Amount,ExpiresTurn=e.ExpiresTurn,RemovedBySilence=e.RemovedBySilence});
 }
}
}
